import { ComponentType } from 'react';

/** One entry per generated layout - what it is, which decompiled AS3 classes drove it, and a lazy loader for the component. */
export interface LayoutRegistryEntry {
    /** The Flash asset name (`<name>_xml`). */
    name: string;
    id: number;
    component: string;
    size: string;
    /** Whether the component renders its own `Frame` (window chrome) at the root. */
    rootIsFrame: boolean;
    /** The component's prop names - `on*` handlers, `caption*`/`src*` overrides, `items*` row slots, `layout`. */
    props: string[];
    /** Props of the main component that forward a sub-component's props: prop name -> sub-component name. */
    nested: Record<string, string>;
    subComponents: string[];
    /** Every sub-component's own props and nested sub-components, so a caller can walk the whole prop tree. */
    subComponentProps: Record<string, { props: string[]; nested: Record<string, string> }>;
    /** Output folder under views/layouts - embedding client library + driving class package (see `layoutFolder` in the generator). */
    folder: string;
    /** Client libraries (`HabboFriendBarCom` -> `friendbar`) whose SWF embedded this layout's XML. */
    libraries: string[];
    /** Decompiled client classes (under scripts/scripts) that build this layout, e.g. `com/sulake/habbo/friendbar/view/tabs/FriendRequestsTab`. */
    as3: string[];
    // eslint-disable-next-line @typescript-eslint/no-explicit-any -- every layout has its own props interface; the browser only ever passes generic handlers.
    load: () => Promise<ComponentType<any>>;
}

